180→      if (r.computable) lines.push(`  ${"".padEnd(18)} raw ${r.raw_rate}, prior ${r.prior} (${r.prior_source}), α=${r.shrinkage_alpha}`);
181→    }
182→    lines.push("");
183→  }
184→  return lines.join("\n");
185→}
