172→export function renderAuthors({ user, agent }) {
173→  const lines = ["# Author confidence", ""];
174→  for (const [label, rows] of [["by user", user], ["by agent", agent]]) {
175→    lines.push(`## ${label}`);
176→    if (rows.length === 0) lines.push("  (no producers seen)");
177→    for (const r of rows) {
178→      const conf = r.computable ? r.confidence.toFixed(3) : "not computable (no cross-person outcomes)";
179→      lines.push(`  ${r.author.padEnd(18)} ${conf.padEnd(42)} V=${r.validated} C=${r.corrected} consumers=${r.distinct_consumers} tasks=${r.distinct_tasks}`);
180→      if (r.computable) lines.push(`  ${"".padEnd(18)} raw ${r.raw_rate}, prior ${r.prior} (${r.prior_source}), α=${r.shrinkage_alpha}`);
181→    }
182→    lines.push("");
183→  }
184→  return lines.join("\n");
185→}
